select t.is_direct, t.identifier as identifier, t.financing_amount as financingAmount, t.id as receiptRepayBaseId, t.write_off_state as writeOffState, t.cash_flow_item as cashFlowItem, t.plan_cash_flow_date as planCashFlowDate, t.plan_cash_flow_amount as planCashFlowAmount, t.cash_flow_code as cashFlowCode, t.financing_code as financingCode, t.fund_channel as fundChannel, t.biz_type as bizType, t.financing_id as financingId from (
) as t where 1 = 1
order by t.plan_cash_flow_date

select t.is_direct, t.identifier as identifier, t.financing_amount as financingAmount, t.id as receiptRepayBaseId, t.write_off_state as writeOffState, t.cash_flow_item as cashFlowItem, t.plan_cash_flow_date as planCashFlowDate, t.plan_cash_flow_amount as planCashFlowAmount, t.plan_principal_amount as planPrincipalAmount, t.plan_interest_amount as planInterestAmount, t.cash_flow_code as cashFlowCode, t.financing_code as financingCode, t.fund_channel as fundChannel, t.biz_type as bizType, t.financing_id as financingId, t.phase as phase from (
) as t where 1 = 1
