select * from fund_receipt_repay_base_info

    and financing_org_id = #{dto.financingOrgId}
    and receipt_repay_code like
        CONCAT('%',#{dto.receiptRepayCode},'%')
    
    and fund_manager = #{dto.fundManager}
    
        and receipt_repay_state = #{dto.receiptRepayState}
    
    
        and financing_biz_type IN
        
            #{item}
        
    
    and financing_amount >= #{dto.financingAmountFrom}
    and financing_amount <= #{dto.financingAmountTo}
    and next_repay_date >= #{dto.dateFrom}
    and next_repay_date <= #{dto.dateTo}
    and create_time >= #{dto.createTimeFrom}
    and create_time <= #{dto.createTimeTo}
    and update_time >= #{dto.updateTimeFrom}

order by create_time desc
